update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Betrachtung von Funktionsstörungen im Hinblick auf den Betrieb der Belüftung müssen Ursachen im Hinblick auf die technischen Einrichtungen (Stromausfall, defekte Aggregate) und Auswirkungen von Funktionsstörungen durch Abwassereinleitungen unterschieden werden. Im Folgenden werden die in der Praxis immer wieder auftretenden Betriebsstörungen und deren mögliche Auswirkung auf die Druckbelüftung beschrieben. — printed p.27', verification_note='md-verified 2026-09-07 (§4.4.1.1, printed p.27) [VC] — the 7 enum options are the guideline''s own sub-clause headings §4.4.1.2 to §4.4.1.8 (Inhalt, printed pp.27-28)', verified_at=now() where id='6a19f3c4-b5dc-40a9-bff1-33feefab2986' and verification_status not in ('verified_against_standard','corrected');

-- flexing_druckabsenkung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Absenkung des Drucks in der Luftleitung darf nur bis auf den hydrostatischen Druck, der am Belüfter anliegt, minus 50 hPa erfolgen. Wird der Druck auf Umgebungsluftdruck abgesenkt, besteht die Gefahr, dass Wasser in die Belüfterelemente eindringt. — printed p.23', verification_note='md-verified 2026-09-07 (§4.3.3.2, printed p.23) [VC] — hard modal ("darf nur"); the 50 hPa is an offset BELOW the hydrostatic pressure at the diffuser, not an absolute pressure', verified_at=now() where id='8c6e75c5-1a0a-475f-96b7-7aded8d7962b' and verification_status not in ('verified_against_standard','corrected');

-- beluefterelement_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Die Methode kann für Platten- und Tellerbelüfter mit nach oben gerichteter Abgasungsfläche eingesetzt werden. Bei Rohrbelüftern ist die Zugänglichkeit an der Unterseite in der Regel ungünstig und die Reinigung mit dem Hochdruckreiniger daher weniger empfehlenswert. | Starrporöse Belüfterelemente können ebenfalls mechanisch mittels Hochdruck-Wasserstrahl gereinigt werden, allerdings wirkt die Reinigung hier lediglich an der Oberfläche und nicht im Inneren des starrporösen Belüftungselements. — printed p.23', verification_note='md-verified 2026-09-07 (§4.3.3.3, printed p.23) [VC] — all four enum options (Platten-, Teller-, Rohr-, starrporöse Belüfter) are printed here', verified_at=now() where id='79bc59f2-0ef5-4369-a9f8-a98feb262eee' and verification_status not in ('verified_against_standard','corrected');

-- membranwerkstoff
