-- reinigungsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Häufig angewendete Methoden sind: | I Dehnung und Entspannung der Membran durch Variation des Luftdurchsatzes (Flexing), | I Einsatz einer automatisierten Luftspülung bei starrporösen Belüfterelementen, | I mechanische Reinigung mit einem rotierenden Hochdruck-Wasserstrahl, | I Eindüsen von Säure in den Luftstrom, | I Fluten mit Reinigungslösung. — printed p.22', verification_note='md-verified 2026-09-07 (§4.3.3.1, printed p.22) [VC] — the 5 enum options are exactly the 5 printed methods. Gate CR-008 anchors this field on §4.3.3.4 instead — clause retag proposed in the STAGED file, block S-5', verified_at=now() where id='ca45fd60-a7d8-4e07-a441-535f44ce4576' and verification_status not in ('verified_against_standard','corrected');

-- instandhaltungsart
update public.fields set verification_status='verified_against_standard', verification_quote='Um eine hohe Verfügbarkeit des Gesamtsystems zu erzielen, sind Instandhaltungsmaßnahmen erforderlich. Die Aufteilung der Tätigkeiten sollte auf DIN 31051 basieren, die Instandhaltung wird dort nach Wartung (Bewahrung des Soll-Zustands), Inspektion (Erfassung des Ist-Zustands) und Instandsetzung (Wiederherstellung des Soll-Zustands) gegliedert. — printed p.21', verification_note='md-verified 2026-09-07 (§4.3.1, printed p.21) [VC] — the three enum options are the DIN 31051 categories the guideline names; the DIN 31051 definitions themselves are NR (other standard)', verified_at=now() where id='710f3fab-6af3-41eb-9299-c8294f5ce6dd' and verification_status not in ('verified_against_standard','corrected');

-- membranbeluefter_wasserueberdeckung
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Stilllegung von Becken - auch bei längeren Revisionen - sind die dortigen Belüfter sachgerecht zu „konservieren“. Üblicherweise ist bei Membranbelüfterelementen eine Wasserüberdeckung von Wasser mit hoher UV-Absorption („trübes Wasser“) erforderlich ( $>50 \mathrm{~cm}$ ). — printed p.28', verification_note='md-verified 2026-09-07 (§4.4.1.8, printed p.28) [VC] — printed hard minimum >50 cm; NO gate enforces it today — see the STAGED file, block S-13', verified_at=now() where id='9e3efecb-0c39-4867-8b06-64ecc48ab972' and verification_status not in ('verified_against_standard','corrected');

