-- leitwand_montiert
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Betrieb von Walzenbelüftern ist sicherzustellen, dass an ihrer Abstromseite Leitschilde entsprechend den Herstellerangaben montiert sind, da diese für einen ordnungsgemäßen Betrieb der Walzen notwendig sind. So führt das Fehlen der Leitwände bzw. der inkorrekte Einbau zu Beeinträchtigungen im Sauerstoffeintrag um bis zu $20 \%$ sowie zu Störungen in der Durchströmung des Beckens. — printed p.30', verification_note='md-verified 2026-09-07 (§5.1.6, printed p.30) [VC] — hard modal, but the obligation is CONDITIONAL ("Bei Betrieb von Walzenbelüftern"); gate CR-009 carries no such guard — see the STAGED file, block S-6', verified_at=now() where id='ec351893-c762-4f5e-b21f-36d36b4210eb' and verification_status not in ('verified_against_standard','corrected');

-- leistungsdichte_ruehrwerk
update public.fields set verification_status='verified_against_standard', verification_quote='Die Leistungsdichte, definiert als die Leistungsaufnahme der Rühraggregate bezogen auf das zu durchmischende Volumen, wird häufig mit $2 \mathrm{~W} / \mathrm{m}^{3}$ bis $5 \mathrm{~W} / \mathrm{m}^{3}$ angegeben, wobei jedoch dieses Maß nur einen Anhaltspunkt für den Betreiber bei der Auswahl und Bewertung der Aggregate liefern kann. [...] Umgekehrt kann bei einem Rühraggregat mit einer hohen spezifischen Schubleistung, einer geeigneten Anordnung des Rühraggregats und einer günstigen Beckenform auch eine Leistungsdichte von $0,8 \mathrm{~W} / \mathrm{m}^{3}$ bis $1,5 \mathrm{~W} / \mathrm{m}^{3}$ ausreichend sein. — printed p.33', verification_note='md-verified 2026-09-07 (§6.1.3, printed p.33) [VC] — the guideline prints TWO separate ranges (2..5 and 0,8..1,5 W/m3) and calls the figure "nur einen Anhaltspunkt"; the single interval 0,8..5 used by gate CR-010 is printed NOWHERE — see the STAGED file, block S-7', verified_at=now() where id='4056e1bd-01ce-4c4e-ad99-3c6aceb1c03e' and verification_status not in ('verified_against_standard','corrected');

-- verweilzeit_tracer
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Bestandsaufnahme bzw. zur Beurteilung des Verweilzeitverhaltens ist die Durchführung eines Tracer-Versuchs oder eine Analyse auf Basis eines dreidimensionalen Simulationsmodells (mit vertretbarem zeitlichem und finanziellem Aufwand) möglich. | Die Wasserbehörden sind vor der Durchführung von Traceruntersuchungen zu informieren; gegebenenfalls ist eine Anzeige und/oder Genehmigung erforderlich. — printed p.34', verification_note='md-verified 2026-09-07 (§6.2.2, printed p.34) [VC]', verified_at=now() where id='d3be81fa-b1a9-4075-bc6b-0ad827a2269f' and verification_status not in ('verified_against_standard','corrected');

-- ablagerungen_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Auch stellen Ablagerungen für Belüfterelemente ein erhebliches Problem dar, wenn diese zu stark von Ablagerungen bedeckt werden und dadurch das Belüftungsergebnis beeinträchtigt wird. | Im Betrieb können Ablagerungen mit einem Stab ertastet oder bei reinen Schlammablagerungen durch mobile TS-Sonden erfasst werden. — printed p.34', verification_note='md-verified 2026-09-07 (§6.2.3, printed p.34) [VC]', verified_at=now() where id='bf2e8c0d-6e21-4f0e-b40f-562d309f3705' and verification_status not in ('verified_against_standard','corrected');

-- ---------------------------------------------------------------- M2292-05 (4 fields)

-- o2_sollkonzentration
update public.fields set verification_status='verified_against_standard', verification_quote='Zielsetzung ist immer, die betrieblich notwendige Sauerstoffsollkonzentration in den verschiedenen Beckenbereichen einzustellen und für eine ausreichende Durchmischung des Reaktorinhalts zu sorgen. — printed p.36', verification_note='md-verified 2026-09-07 (§7.1, printed p.36) [VC] — the strategies themselves are NR: "Diese sind ausführlich im Arbeitsblatt DWA-A 268 beschrieben"', verified_at=now() where id='94e605c2-c141-4f66-ae4d-22b2a57393b0' and verification_status not in ('verified_against_standard','corrected');

-- o2_min_p_elimination
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Anlagen mit erhöhter biologischer Phosphatelimination ist zudem zu beachten, dass im gesamten aeroben Bereich eine ausreichende Sauerstoffkonzentration ( $>0,5 \mathrm{mg} / \mathrm{l} \mathrm{O}_{2}$ ) vorhanden sein muss, um eine ungewollte P -Rücklösung in der Nitrifikationszone zu verhindern. — printed p.37', verification_note='md-verified 2026-09-07 (§7.2, printed p.37) [VC] — hard modal ("muss"), strict >0,5 mg/l; the obligation is conditional on "Anlagen mit erhöhter biologischer Phosphatelimination" and there is no guard field for that condition — see the STAGED file, block S-9', verified_at=now() where id='1048c72f-c979-4a03-b5d7-1e2c23f7f8f6' and verification_status not in ('verified_against_standard','corrected');

-- o2_min_winter_stabilisierung
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Sicherstellung eines ausreichenden, aeroben Schlammalters sollte im Winter-Dauerbetrieb eine Sauerstoffsollkonzentration von $>1 \mathrm{mg} / \mathrm{l}_{2}$ angestrebt werden. — printed p.37', verification_note='md-verified 2026-09-07 (§7.3, printed p.37) [VC] — soft modal ("sollte ... angestrebt werden"); the md transcript drops the O in "mg/l O2" (OCR artifact), quoted verbatim', verified_at=now() where id='074aad3c-4008-4580-ae69-d613d1b2e2ce' and verification_status not in ('verified_against_standard','corrected');

-- stabilisierungsnachweis
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Nachweis der Stabilisierung stehen unterschiedliche Verfahren zur Verfügung, am einfachsten ist zur Erstbeurteilung der organische Trockensubstanzanteil (Glühverlust). Weitere Kennwerte können dem Merkblatt DWA-M 368 entnommen werden. — printed p.37', verification_note='md-verified 2026-09-07 (§7.2, printed p.37) [VC] — the single enum option (Glühverlust) is the only method this Merkblatt names; the "weitere Kennwerte" are NR (DWA-M 368)', verified_at=now() where id='f3d21696-ff6d-4a1d-b59d-53809a413e62' and verification_status not in ('verified_against_standard','corrected');

