-- EW_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='Kurzzeichen & Einheit & Erläuterung | $E W_{\text {csB }, 120}$ & E & Einwohnerwert ( $E W=E Z+E G W$ ) bezogen auf den CSB mit einer spezifischen Belastung von $120 \mathrm{~g} /(\mathrm{E} \cdot \mathrm{d})$ | Die Schmutzfrachtbelastung wird als Jahresmittelwert der CSB-Fracht unter Berücksichtigung ei- ner einwohnerspezifischen Fracht in Höhe von $120 \mathrm{~g} /(\mathrm{E} \cdot \mathrm{d})$ im Zulauf der Anlage ermittelt. — printed p.11-13 and p.39', verification_note='md-verified 2026-09-07 (§3.2 + §8.2.2, printed p.11-13/p.39) [VC] — the md breaks "einer" as "ei- ner" mid-line (OCR artifact), quoted verbatim. The symbol table writes EW_CSB,120, Gl.3 writes EW_CSB. Determining the EW itself defers to DWA-A 131 (NR)', verified_at=now() where id='699979a3-adbb-4ead-aa0e-511bf02a2166' and verification_status not in ('verified_against_standard','corrected');

