-- e_Bel
update public.fields set verification_status='verified_against_standard', verification_quote='Der spezifische Energieverbrauch der Belüftung ergibt unter Benutzung des Gesamtenergieverbrauchs (siehe 8.2.1) und der behandelten jährlichen Schmutzfracht eine Kennzahl zur vergleichenden Beurteilung der Energieeffizienz des Belüftungssystems auch mit anderen Anlagen. | e_{\mathrm{Bel}}=\frac{E_{\mathrm{Bel}}}{E W_{\mathrm{CSB}}} \quad(\mathrm{kWh} /(\mathrm{E} \cdot \mathrm{a})) \tag{3} — printed p.39', verification_note='md-verified 2026-09-07 (§8.2.2 Gl.3, printed p.39) [VC] — derived value; dimensional check (kWh/a)/(E) = kWh/(E*a) matches the field unit', verified_at=now() where id='c4495a09-bfdc-4f02-a045-35dbf7f8d70f' and verification_status not in ('verified_against_standard','corrected');

-- e_Bel_OV
update public.fields set verification_status='verified_against_standard', verification_quote='Daher eignet sich die spezifische Energieeffizienz der Belüftung insbesondere für eine detaillierte Beurteilung der jeweiligen Anlage als Überjahresvergleich, aber auch zur Beurteilung der Energieeffizienz im Vergleich zu anderen Anlagen. | e_{\mathrm{Bel}, \mathrm{OV}}=\frac{E_{\mathrm{Bel}}}{O V_{\mathrm{h}, \mathrm{aM}} \cdot 8.760} \quad\left(\mathrm{kWh} / \mathrm{kg} \mathrm{O}_{2}\right) \tag{4} — printed p.39', verification_note='md-verified 2026-09-07 (§8.2.3 Gl.4, printed p.39) [VC] — derived; the printed "8.760" is the German thousands notation for 8760 h/a and is encoded as 8760 (correct); dimensional check (kWh/a)/((kg/h)*8760 h/a) = kWh/kg O2 matches the field unit', verified_at=now() where id='caa1b5ca-9d82-484c-9493-6cdf25f969c9' and verification_status not in ('verified_against_standard','corrected');

-- p_spez_p
update public.fields set verification_status='verified_against_standard', verification_quote='Kurzzeichen & Einheit & Erläuterung | $p_{\text {spez.p }}$ & $\mathrm{W} /\left(\left(\mathrm{m}_{\mathrm{N}}^{3} / \mathrm{h}\right) \cdot \mathrm{hPa}\right)$ & Spezifische Leistung für den Drucklufterzeuger bezogen auf die Druckdifferenz | p_{\text {spez }, \mathrm{p}}=\frac{P_{\text {Gebl }}(\mathrm{W})}{Q_{\mathrm{L}, \mathrm{~N}}\left(\mathrm{~m}^{3} / \mathrm{s}\right) \cdot \Delta p(\mathrm{~Pa})} & \left(\mathrm{Ws} /\left(\mathrm{m}_{\mathrm{N}}^{3} \cdot \mathrm{~Pa}\right)\right) — printed p.11-13 and p.40', verification_note='md-verified 2026-09-07 (§3.2 + §8.2.4 Gl.5, printed p.11-13/p.40) [VC] — UNIT FINDING: the field carries the §3.2 unit W/((mN3/h)*hPa) while Gl.5 declares Ws/(mN3*Pa) with P in W, Q in m3/s, dp in Pa. The two printed unit declarations differ by a factor 36, and the encoded inputs (P_Gebl in kW, Q_L_N in mN3/h, dp in hPa) add a further factor 1000 — see the STAGED file, block S-8. Not corrected here (SR-2/ruling required)', verified_at=now() where id='767629e7-3195-4e63-b499-8abaa6e78302' and verification_status not in ('verified_against_standard','corrected');

-- p_spez_h
update public.fields set verification_status='verified_against_standard', verification_quote='Kurzzeichen & Einheit & Erläuterung | $p_{\text {spez,h }}$ & $\mathrm{W} /\left(\left(\mathrm{m}_{\mathrm{N}}^{3} / \mathrm{h}\right) \cdot \mathrm{m}\right)$ & Spezifische Leistung für den Drucklufterzeuger bezogen auf die Einblastiefe | p_{\text {spez }, \mathrm{h}}=\frac{P_{\text {Gebl }}(\mathrm{W})}{Q_{\mathrm{L}, \mathrm{~N}}\left(\mathrm{~m}^{3} / \mathrm{s}\right) \cdot h_{\mathrm{D}}(\mathrm{~m})} & \left(\mathrm{Ws} /\left(\mathrm{m}_{\mathrm{N}}^{3} \cdot \mathrm{~m}\right)\right) \tag{6} — printed p.11-13 and p.40', verification_note='md-verified 2026-09-07 (§3.2 + §8.2.4 Gl.6, printed p.11-13/p.40) [VC] — UNIT FINDING: §3.2 declares W/((mN3/h)*m), Gl.6 declares Ws/(mN3*m) with Q in m3/s — a factor 3600 between the guideline''s own two declarations, plus a factor 1000 from P_Gebl being encoded in kW — see the STAGED file, block S-8', verified_at=now() where id='61cc2f16-9fcd-4f1e-86c3-b1422df5b16b' and verification_status not in ('verified_against_standard','corrected');

-- e_Ruehr
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Einordnung der anlagenspezifischen energetischen Effizienz von Rührwerken wird empfohlen, die Kennzahl des Jahresenergieverbrauchs der Rührwerke im Verhältnis zum durchmischten Beckenvolumen zu ermitteln: | e_{\text {Rühr }}=\frac{E_{\text {Rühr }}}{V_{\text {Rühr }} \cdot 8,76} \quad\left(\mathrm{~W} / \mathrm{m}^{3}\right) \tag{7} — printed p.41', verification_note='md-verified 2026-09-07 (§8.2.5 Gl.7, printed p.41) [VC] — derived; the constant is the printed 8,76 (= 8760 h/a / 1000 W/kW) and is encoded as 8.76, NOT 8760: dimensional check (kWh/a)/(m3*8,76) = W/m3 matches the field unit', verified_at=now() where id='919b100d-f387-4fec-bd0c-89f21b682b7a' and verification_status not in ('verified_against_standard','corrected');

-- DV
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Beurteilung der energetischen Effizienz des Luftverteilungssystems kann das Druckverhältnis der Druckerhöhung in der Drucklufterzeugerstufe bezogen auf den hydraulischen Gegendruck durch die Einblastiefe berechnet werden. | Ein typischer Wert für das Druckverhältnis DV bei feinblasigen Belüftungssystemen beträgt 1,2. — printed p.41', verification_note='md-verified 2026-09-07 (§8.2.6, printed p.41) [VC] — derived, dimensionless (dp[hPa]/(h_D*10*9,81) = dp/(98,1*h_D) hPa/hPa). The printed 1,2 is a "typischer Wert", not a limit; no gate uses DV — see the STAGED file, block S-15', verified_at=now() where id='b5f5a9ff-aaca-4b07-bd86-abf68b329794' and verification_status not in ('verified_against_standard','corrected');

-- energieverbrauch_abweichung
update public.fields set verification_status='verified_against_standard', verification_quote='Bei signifikanter Veränderung des Energieverbrauchs für Belüftung und Durchmischung im Vergleich zum Vorjahr (> $10 \%$ ) ist zunächst zu prüfen, ob dies mit einer Erhöhung der Schmutzfrachtbelastung korrespondiert. Sofern die Schmutzfrachtbelastung konstant geblieben ist, sollte bei Druckbelüftungssystemen geprüft werden, ob es im Betrachtungszeitraum zu einem Anstieg des Drucks in der Luftleitung gekommen ist. — printed p.42', verification_note='md-verified 2026-09-07 (§8.4, printed p.42) [VC] — printed threshold is >10 %; the symmetric -10 % lower bound of gate CR-014 is an interpretation of "Veränderung", not printed — see the STAGED file, block S-11', verified_at=now() where id='1e96b469-6a2d-478c-8c24-660703492e4e' and verification_status not in ('verified_against_standard','corrected');

