update public.fields set verification_status='verified_against_standard', verification_quote='Die Messungen können je nach Fragestellung und Untersuchungsziel zum einen großtechnisch im Belebungsbecken (in Reinwasser oder in belebtem Schlamm) oder alternativ im (klein-)technischen Maßstab als sogenannte Shoptests durchgeführt werden (siehe 4.3.4.4). Generell sind bei diesen Messungen die Vorgaben und Hinweise aus dem Merkblatt DWA-M 209 zu beachten. — printed p.24', verification_note='md-verified 2026-09-07 (§4.3.4.1, printed p.24) [VC] — the three enum options are exactly the three printed measurement settings (§4.3.4.2 Reinwasser p.25, §4.3.4.3 belebter Schlamm p.25, §4.3.4.4 Shoptest p.25). The measurement procedure itself is NR (DWA-M 209)', verified_at=now() where id='a165549e-78b3-440a-a381-2cf5a5eb7d6f' and verification_status not in ('verified_against_standard','corrected');

